INSERT INTO `coaches` (`id`, `nombre_coach`, `descripcion_coach`, `id_disciplina`, `activo`, `fecha`) VALUES
(2, 'Viry', 'Para mí, Barre es una forma de reconectar. En mis clases me enfoco en que te sientas segura, cómoda y acompañada. Cuido mucho la postura, la alineación y los detalles que hacen la diferencia. Mi intención es que vivas el ejercicio como un espacio de autocuidado, donde entrenas con amor y sin prisa.', 1, 1, '2025-09-18 03:32:52'),
(4, 'Karina', 'Soy el tipo de entrenadora que quiere que disfrutes cada segundo del reto. Me gusta mantenerte activa, conectada y motivada. Mis clases son dinámicas, con ritmo y buena energía. Quiero que sientas el poder de tu cuerpo en movimiento y salgas sabiendo que diste lo mejor de ti, sin presiones, pero con intención.', 1, 1, '2025-09-30 21:25:15'),
(5, 'Natalia', 'Como coach, busco que cada movimiento sea una invitación a escucharte, a sentir tu cuerpo y a encontrar en la fuerza una nueva forma de calma. Creo en el poder del movimiento consciente, en moverte con propósito y dejar que la energía fluya.', 1, 1, '2025-11-01 03:55:15');
